window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4efbafe1e4baf502"]={"versions": [{"id": "FIG-4efbafe1e4baf502", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Variabilitätsmodellierung nach FODA-Notation / Feature-Oriented Domain Analysis) gemäß dem Dokument <em>AUTOSAR_FO_TR_Features</em> (Foundation).</li>\n<li><strong>Technischer Zweck:</strong> Plattformübergreifende funktionale Dekomposition des Domänen-Features <strong>Storage</strong> in konkrete Sub-Features für die jeweiligen Plattformausprägungen (AUTOSAR Classic Platform vs. AUTOSAR Adaptive Platform). Es dient der Anforderungsverfolgung, Systemdefinition und Variantenkonfiguration auf Gesamtfahrzeugebene.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten / Entitäten (Features):</strong></li>\n<li><code>FO_TR_FEAT_00055</code> (<strong>Storage</strong>): Abstraktes Eltern-Feature (Root/Compound Feature) der AUTOSAR Foundation für persistente Datenspeicherung.</li>\n<li><code>FO_TR_FEAT_00056</code> (<strong>NVRAM_Access</strong>): Untergeordnetes Feature zur persistenten Datenspeicherung in der AUTOSAR Classic Platform (CP).</li>\n<li><code>FO_TR_FEAT_00059</code> (<strong>Persistency</strong>): Untergeordnetes Feature zur persistenten Datenspeicherung in der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Dekompositions-Kanten mit ungefülltem Kreis (Hollow Circle):</strong> Kennzeichnen <strong>optionale Sub-Features</strong> (<em>Optional Features</em>).</li>\n<li><strong>Variabilitätsregel:</strong> Eine Implementierung bzw. ein Steuergeräte-Kontext (Machine / ECU Instance) kann <code>NVRAM_Access</code>, <code>Persistency</code>, keines von beiden oder beide (in gemischten bzw. Gateway-Architekturen) allozieren, um dem übergeordneten Speicherbedarf (<code>Storage</code>) zu genügen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statische Variabilitätsabbildung:</strong> Das Diagramm modelliert rein statische Feature-Abhängigkeiten; es existiert kein sequenzieller Kontroll- oder Datenfluss.</li>\n<li><strong>Plattformspezifische Laufzeit-Pfade bei Feature-Aktivierung:</strong></li>\n<li><strong>Bei Selektion von <code>FO_TR_FEAT_00056</code> (CP - NVRAM_Access):</strong></li>\n<li>Blockbasierter Zugriff über den NVRAM Manager (<code>NvM</code>).</li>\n<li>Abstraktion via Memory Abstraction Interface (<code>MemIf</code>) zu Flash EEPROM Emulation (<code>Fee</code>) bzw. EEPROM Abstraction (<code>Ea</code>).</li>\n<li>Asynchrones Lesen/Schreiben (Request/Job-Verarbeitung, Polling oder Callbacks via <code>NvM_JobEndNotification</code> / <code>NvM_JobErrorNotification</code>), Fehlerbehandlung via <code>Dem</code> (z. B. <code>NVM_E_INTEGRITY_FAILED</code>).</li>\n<li><strong>Bei Selektion von <code>FO_TR_FEAT_00059</code> (AP - Persistency):</strong></li>\n<li>Objekt- und filebasierter Zugriff über den Functional Cluster <code>ara::per</code>.</li>\n<li>Schnittstellen für Key-Value Storage (<code>ara::per::KeyValueStorage</code>) und File Storage (<code>ara::per::FileStorage</code>).</li>\n<li>Synchrone und asynchrone C++14/C++17 API-Methoden (Rückgabe via <code>ara::core::Result</code> / <code>ara::core::Future</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Systemkonfiguration & Architektur-Allokation:</strong></li>\n<li>Auf System-Definitionsebene entscheidet die Bindung dieser Features über die erforderlichen BSW-Stacks bzw. Plattform-Cluster.</li>\n<li><strong>Classic Platform (<code>FO_TR_FEAT_00056</code>):</strong></li>\n<li>Erfordert die Integration des NvM-Stacks (BSW-Module <code>NvM</code>, <code>MemIf</code>, <code>Fee</code>/<code>Ea</code>, <code>Fls</code>/<code>Eep</code>).</li>\n<li>NVRAM-Blockverwaltung, Redundanz-Layouts (CRC, redundante Blöcke), NvM-RAM-Spiegel und NV-Block-SWCs müssen in der ARXML-Methodik definiert werden.</li>\n<li><strong>Adaptive Platform (<code>FO_TR_FEAT_00059</code>):</strong></li>\n<li>Erfordert das Deployment des <code>ara::per</code>-Dienstes im POSIX-OS-Umfeld.</li>\n<li>Manifest-Modellierung umfasst <code>PersistencyPortPrototype</code>, <code>PersistencySharedDataElement</code> sowie Redundanz-/Integritätsprüfungen auf File- und Key-Value-Ebene.</li>\n<li><strong>Einschränkung:</strong> Die Features schließen sich gegenseitig nicht aus, laufen jedoch auf disjunkten Laufzeitumgebungen (RTE/Microcontroller vs. ARA/POSIX-Machine).</li>\n</ul>"}, {"id": "FIG-af1e966147ebc366", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Diagramm / Feature-Baum (Variabilitätsmodellierung nach FODA-Notation / Feature-Oriented Domain Analysis) gemäß dem Dokument <em>AUTOSAR_FO_TR_Features</em> (Foundation).</li>\n<li><strong>Technischer Zweck:</strong> Plattformübergreifende funktionale Dekomposition des Domänen-Features <strong>Storage</strong> in konkrete Sub-Features für lokale und entfernte persistente Datenspeicherung über AUTOSAR-Plattformen hinweg. Es dient der Anforderungsverfolgung, Systemdefinition und Variantenkonfiguration auf Gesamtfahrzeugebene.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Knoten / Entitäten (Features):</strong></li>\n<li><code>FO_TR_FEAT_00055</code> (<strong>Storage</strong>): Abstraktes Eltern-Feature (Root/Compound Feature) der AUTOSAR Foundation für persistente Datenspeicherung.</li>\n<li><code>FO_TR_FEAT_00260</code> (<strong>Remote_Persistency</strong>): Untergeordnetes Feature für entfernte persistente Speicherung über Netzwerkgrenzen hinweg.</li>\n<li><code>FO_TR_FEAT_00056</code> (<strong>NVRAM_Access</strong>): Untergeordnetes Feature zur persistenten Datenspeicherung in der AUTOSAR Classic Platform (CP).</li>\n<li><code>FO_TR_FEAT_00059</code> (<strong>Persistency</strong>): Untergeordnetes Feature zur persistenten Datenspeicherung in der AUTOSAR Adaptive Platform (AP).</li>\n<li><strong>Beziehungen & Semantik:</strong></li>\n<li><strong>Dekompositions-Kanten mit ungefülltem Kreis (Hollow Circle):</strong> Kennzeichnen <strong>optionale Sub-Features</strong> (<em>Optional Features</em>).</li>\n<li><strong>Variabilitätsregel:</strong> Eine Implementierung bzw. ein Steuergeräte-Kontext (Machine / ECU Instance) kann <code>Remote_Persistency</code>, <code>NVRAM_Access</code>, <code>Persistency</code>, eine beliebige Kombination davon oder keines allozieren, um dem übergeordneten Speicherbedarf (<code>Storage</code>) zu genügen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Statische Variabilitätsabbildung:</strong> Das Diagramm modelliert rein statische Feature-Abhängigkeiten; es existiert kein sequenzieller Kontroll- oder Datenfluss.</li>\n<li><strong>Plattformspezifische Laufzeit-Pfade bei Feature-Aktivierung:</strong></li>\n<li><strong>Bei Selektion von <code>FO_TR_FEAT_00260</code> (Remote_Persistency):</strong></li>\n<li>Zugriff auf persistente Speicherressourcen über Netzwerk- oder Inter-ECU-Kommunikationsmechanismen (z. B. via Remote-Persistency-Clients/Services bzw. Netzwerkschnittstellen).</li>\n<li><strong>Bei Selektion von <code>FO_TR_FEAT_00056</code> (CP - NVRAM_Access):</strong></li>\n<li>Blockbasierter Zugriff über den NVRAM Manager (<code>NvM</code>).</li>\n<li>Abstraktion via Memory Abstraction Interface (<code>MemIf</code>) zu Flash EEPROM Emulation (<code>Fee</code>) bzw. EEPROM Abstraction (<code>Ea</code>).</li>\n<li>Asynchrones Lesen/Schreiben (Request/Job-Verarbeitung, Polling oder Callbacks via <code>NvM_JobEndNotification</code> / <code>NvM_JobErrorNotification</code>), Fehlerbehandlung via <code>Dem</code> (z. B. <code>NVM_E_INTEGRITY_FAILED</code>).</li>\n<li><strong>Bei Selektion von <code>FO_TR_FEAT_00059</code> (AP - Persistency):</strong></li>\n<li>Objekt- und filebasierter Zugriff über den Functional Cluster <code>ara::per</code>.</li>\n<li>Schnittstellen für Key-Value Storage (<code>ara::per::KeyValueStorage</code>) und File Storage (<code>ara::per::FileStorage</code>).</li>\n<li>Synchrone und asynchrone C++14/C++17 API-Methoden (Rückgabe via <code>ara::core::Result</code> / <code>ara::core::Future</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Systemkonfiguration & Architektur-Allokation:</strong></li>\n<li>Auf System-Definitionsebene entscheidet die Bindung dieser Features über die erforderlichen BSW-Stacks, Plattform-Cluster und Kommunikationspfade.</li>\n<li><strong>Remote Persistency (<code>FO_TR_FEAT_00260</code>):</strong></li>\n<li>Erfordert Kommunikationsprotokolle und Dienste zur Übertragung und Synchronisation persistenter Daten mit entfernten Speicherinstanzen.</li>\n<li><strong>Classic Platform (<code>FO_TR_FEAT_00056</code>):</strong></li>\n<li>Erfordert die Integration des NvM-Stacks (BSW-Module <code>NvM</code>, <code>MemIf</code>, <code>Fee</code>/<code>Ea</code>, <code>Fls</code>/<code>Eep</code>).</li>\n<li>NVRAM-Blockverwaltung, Redundanz-Layouts (CRC, redundante Blöcke), NvM-RAM-Spiegel und NV-Block-SWCs müssen in der ARXML-Methodik definiert werden.</li>\n<li><strong>Adaptive Platform (<code>FO_TR_FEAT_00059</code>):</strong></li>\n<li>Erfordert das Deployment des <code>ara::per</code>-Dienstes im POSIX-OS-Umfeld.</li>\n<li>Manifest-Modellierung umfasst <code>PersistencyPortPrototype</code>, <code>PersistencySharedDataElement</code> sowie Redundanz-/Integritätsprüfungen auf File- und Key-Value-Ebene.</li>\n<li><strong>Einschränkung:</strong> Die Features schließen sich auf Architekturebene nicht gegenseitig aus, sondern können je nach Steuergeräte-Rolle kombiniert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-4efbafe1e4baf502", "to": "FIG-af1e966147ebc366", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neues optionales Sub-Feature <code>FO_TR_FEAT_00260</code> (<code>Remote_Persistency</code>) unterhalb von <code>FO_TR_FEAT_00055</code> (<code>Storage</code>) mit Dekompositionskante und ungefülltem Kreis (optional) hinzugefügt.</li>\n<li>Layout des Feature-Baums von zwei auf drei Kindknoten erweitert.</li>\n</ul>"}]};
